import "core-js/modules/es.array.push.js";
import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.map.js";
import AdminNavigationBar from './AdminNavigationBar.vue';
import { ref, computed, onMounted } from "vue";
import { db } from "@/firebase";
import { collection, doc, updateDoc, onSnapshot, serverTimestamp, arrayUnion } from "firebase/firestore";
import { useRouter } from "vue-router";
import { getAuth } from "firebase/auth";
export default {
  components: {
    AdminNavigationBar
  },
  setup() {
    const bids = ref([]);
    const loading = ref(true);
    const isEvaluating = ref(false);
    const selectedBid = ref({});
    const technicalScore = ref(0);
    const financialScore = ref(0);
    const remarks = ref("");
    const docs = ref({
      secDti: false,
      mayorPermit: false,
      taxClearance: false,
      auditedFs: false,
      technicalForm: false,
      financialForm: false
    });
    const isSidebarCollapsed = ref(false);

    // Add these refs to fix no-undef errors
    const searchQuery = ref("");
    const statusFilter = ref("all");
    const router = useRouter();

    // Confirmation modal logic
    const showConfirm = ref(false);
    const confirmActionType = ref("");
    const confirmBid = ref(null);

    // Computed values for stats
    const pendingBidsCount = computed(() => bids.value.filter(bid => !bid.status || bid.status === "pending").length);
    const approvedBidsCount = computed(() => bids.value.filter(bid => bid.status === "approved").length);
    const rejectedBidsCount = computed(() => bids.value.filter(bid => bid.status === "rejected").length);
    const filteredBids = computed(() => {
      let result = [...bids.value];

      // Apply status filter
      if (statusFilter.value !== "all") {
        result = result.filter(bid => !bid.status && statusFilter.value === "pending" || bid.status?.toLowerCase() === statusFilter.value.toLowerCase());
      }

      // Apply search query
      if (searchQuery.value) {
        const query = searchQuery.value.toLowerCase();
        result = result.filter(bid => bid.bidderName && bid.bidderName.toLowerCase().includes(query) || bid.description && bid.description.toLowerCase().includes(query));
      }
      return result;
    });
    const fetchBids = async () => {
      try {
        loading.value = true;

        // Set up real-time listener for bids collection
        const unsubscribe = onSnapshot(collection(db, "bids"), snapshot => {
          bids.value = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data(),
            submissionDate: doc.data().submissionDate || null,
            description: doc.data().description || "",
            notes: doc.data().notes || ""
          }));
          loading.value = false;
        });

        // Return unsubscribe function for cleanup
        return unsubscribe;
      } catch (error) {
        console.error("Error fetching bids:", error);
        showNotification("Failed to fetch bids. Please try again.", "error");
        loading.value = false;
      }
    };
    const openEvaluationModal = bid => {
      selectedBid.value = {
        ...bid
      };
      technicalScore.value = bid.technicalScore || 0;
      financialScore.value = bid.financialScore || 0;
      remarks.value = bid.remarks || "";
      docs.value = bid.docs ? {
        ...docs.value,
        ...bid.docs
      } : {
        ...docs.value
      };
      isEvaluating.value = true;
    };
    const closeEvaluationModal = () => {
      isEvaluating.value = false;
      selectedBid.value = {};
      technicalScore.value = 0;
      financialScore.value = 0;
      remarks.value = "";
      docs.value = {
        secDti: false,
        mayorPermit: false,
        taxClearance: false,
        auditedFs: false,
        technicalForm: false,
        financialForm: false
      };
    };
    const totalScore = computed(() => {
      return Number(technicalScore.value) * 0.6 + Number(financialScore.value) * 0.4;
    });

    // Confirmation modal for approve/reject
    const confirmApprove = bid => {
      confirmActionType.value = "approve";
      confirmBid.value = bid;
      showConfirm.value = true;
    };
    const confirmReject = bid => {
      confirmActionType.value = "reject";
      confirmBid.value = bid;
      showConfirm.value = true;
    };
    const performConfirmAction = async () => {
      if (!confirmBid.value) return;
      const auth = getAuth();
      const user = auth.currentUser;
      const bidRef = doc(db, "bids", confirmBid.value.id);
      const status = confirmActionType.value === "approve" ? "approved" : "rejected";
      const historyEntry = {
        status: status.charAt(0).toUpperCase() + status.slice(1),
        by: user ? user.displayName || user.email || user.uid : "Unknown",
        at: new Date(),
        remarks: remarks.value
      };
      try {
        await updateDoc(bidRef, {
          status,
          [`${status}Date`]: new Date(),
          statusHistory: arrayUnion(historyEntry),
          evaluatedBy: user ? user.displayName || user.email || user.uid : "Unknown",
          evaluatedAt: serverTimestamp(),
          remarks: remarks.value
        });
        showNotification(`Bid ${status} successfully!`);
        showConfirm.value = false;
        confirmBid.value = null;
      } catch (error) {
        showNotification(`Failed to ${status} bid.`, "error");
      }
    };

    // Submit evaluation (with audit trail and status history)
    const submitEvaluation = async () => {
      if (!selectedBid.value.id) return;
      const auth = getAuth();
      const user = auth.currentUser;
      const bidRef = doc(db, "bids", selectedBid.value.id);
      const historyEntry = {
        status: "Evaluated",
        by: user ? user.displayName || user.email || user.uid : "Unknown",
        at: new Date(),
        remarks: remarks.value
      };
      try {
        await updateDoc(bidRef, {
          technicalScore: Number(technicalScore.value),
          financialScore: Number(financialScore.value),
          totalScore: Number(totalScore.value),
          remarks: remarks.value,
          docs: docs.value,
          evaluatedBy: user ? user.displayName || user.email || user.uid : "Unknown",
          evaluatedAt: serverTimestamp(),
          statusHistory: arrayUnion(historyEntry)
        });
        showNotification("Bid evaluation submitted successfully!");
        closeEvaluationModal();
      } catch (error) {
        showNotification("Failed to submit evaluation.", "error");
      }
    };
    const formatCurrency = amount => {
      if (!amount) return "$0.00";
      return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: "USD"
      }).format(amount);
    };
    const formatDate = timestamp => {
      if (!timestamp) return "N/A";

      // If timestamp is a Firestore Timestamp, convert to JS Date
      const date = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric"
      });
    };
    const truncateDescription = (text, maxLength = 100) => {
      if (!text) return "";
      if (text.length <= maxLength) return text;
      return text.substring(0, maxLength) + "...";
    };
    const showNotification = (message, type = "success") => {
      // Create notification element
      const notification = document.createElement("div");
      notification.className = `notification ${type}`;
      notification.textContent = message;
      document.body.appendChild(notification);

      // Add animation class after a short delay
      setTimeout(() => {
        notification.classList.add("show");
      }, 10);

      // Remove notification after timeout
      setTimeout(() => {
        notification.classList.remove("show");
        setTimeout(() => {
          document.body.removeChild(notification);
        }, 300);
      }, 3000);
    };
    const navigateToBidEvaluation = bidId => {
      router.push({
        name: "BidEvaluation",
        params: {
          id: bidId
        }
      });
    };
    onMounted(fetchBids);

    // Sidebar toggle handler (expects AdminNavigationBar emits 'toggle-sidebar')
    const toggleSidebar = () => {
      isSidebarCollapsed.value = !isSidebarCollapsed.value;
    };
    return {
      bids,
      loading,
      isEvaluating,
      selectedBid,
      technicalScore,
      financialScore,
      totalScore,
      remarks,
      docs,
      openEvaluationModal,
      closeEvaluationModal,
      submitEvaluation,
      showConfirm,
      confirmActionType,
      confirmApprove,
      confirmReject,
      performConfirmAction,
      searchQuery,
      statusFilter,
      filteredBids,
      pendingBidsCount,
      approvedBidsCount,
      rejectedBidsCount,
      formatCurrency,
      formatDate,
      truncateDescription,
      navigateToBidEvaluation,
      isSidebarCollapsed,
      toggleSidebar
    };
  }
};
